struct PID_Controller{
    float Kp;           
    float Ki;           
    float Kd;           
    float prev_error;   
    float integrator;   
    float out_min;      
    float out_max;      
    float deadzone;     
};

PID_Controller g_PidCtrl_PIDConverter = {
    .Kp = 0.85f,        
    .Ki = 0.15f,       
    .Kd = 0.05f,
    .prev_error = 0.0f,
    .integrator = 0.0f,
    .out_min = 5.0f,    
    .out_max = 98.0f,   
    .deadzone = 0.2f    
};

float PidCtrl_PIDCompute(PID_Controller *pid, float setpoint, float feedback, float dt) 
{
    float error = setpoint - feedback;

    if (error > -pid->deadzone && error < pid->deadzone) 
	{
        error = 0.0f;
    }

    float p_term = pid->Kp * error;

    pid->integrator += (pid->Ki * error * dt);
    if (pid->integrator > pid->out_max) pid->integrator = pid->out_max;
    if (pid->integrator < pid->out_min) pid->integrator = pid->out_min;

    float d_term = 0.0f;
    if (dt > 0.0f) 
	{
        d_term = pid->Kd * (error - pid->prev_error) / dt;
    }
    pid->prev_error = error;

    float output = p_term + pid->integrator + d_term;
    if (output > pid->out_max) output = pid->out_max;
    if (output < pid->out_min) output = pid->out_min;

    return output;
}

