static uint8_t s_alive_counter_DiagFrame_DTC = 0;
void Send_ActiveDTC_Frames(void)
{
    uint8_t active_indices[TOTAL_DTCS];
    uint8_t active_count = 0;

	for (uint8_t i = 0; i < TOTAL_DTCS; i++)
    {
        if (g_dtc_table[i].fault_status != DTC_STATUS_MISSING)
        {
            active_indices[active_count++] = i;
        }
    }

    if (active_count == 0)
    {
        uint8_t checksum = 0;
        Uart_TxByte(0xA5); checksum += 0xA5;
        
        for (uint8_t p = 0; p < 8; p++)
        {
            Uart_TxByte(0x00); 
            checksum += 0x00;
        }

        Uart_TxByte(s_alive_counter_DiagFrame_DTC); 
        checksum += s_alive_counter_DiagFrame_DTC;
        
        Uart_TxByte(checksum);
        Uart_TxByte(0x0D);

        s_alive_counter_DiagFrame_DTC = (s_alive_counter_DiagFrame_DTC + 1) % 16;
        return;
    }

    uint8_t total_frames = (active_count + 1) / 2; 

    for (uint8_t f = 0; f < total_frames; f++)
    {
        uint8_t checksum = 0;

        Uart_TxByte(0xA5); 
        checksum += 0xA5;

        for (uint8_t d = 0; d < 2; d++)
        {
            uint8_t dtc_idx_array_pos = (f * 2) + d;
            if (dtc_idx_array_pos < active_count)
            {
                uint8_t real_dtc_index = active_indices[dtc_idx_array_pos];
                uint32_t code = g_dtc_table[real_dtc_index].dtc_code;
                uint8_t status = g_dtc_table[real_dtc_index].fault_status;

                for (int8_t b = 2; b >= 0; b--)
                {
                    uint8_t byte_val = (uint8_t)((code >> (b * 8)) & 0xFF);
                    Uart_TxByte(byte_val); 
                    checksum += byte_val;
                }
                
                Uart_TxByte(status); 
                checksum += status;
            }
            else
            {
                for (uint8_t p = 0; p < 4; p++)
                {
                    Uart_TxByte(0x00); 
                    checksum += 0x00;
                }
            }
        }

        Uart_TxByte(s_alive_counter_DiagFrame_DTC); 
        checksum += s_alive_counter_DiagFrame_DTC;
        
        Uart_TxByte(checksum);
        Uart_TxByte(0x0D);

        s_alive_counter_DiagFrame_DTC = (s_alive_counter_DiagFrame_DTC + 1) % 16;
    }
}

