{
    uint8_t checksum = 0;
    
    Uart_TxByte(0x7F); checksum += 0x7F;
    Uart_TxByte(sid); checksum += sid;
    Uart_TxByte(nrc); checksum += nrc;
    
    for (uint8_t i = 0; i < 7; i++) {
        Uart_TxByte(0x00);
        checksum += 0x00;
    }
    
    Uart_TxByte(checksum);
    Uart_TxByte(0x0D); 
}

void Send_PositiveResponse(uint8_t sid, const uint8_t *data, uint8_t data_len)
{
    uint8_t checksum = 0;
    uint8_t pos_sid = sid + 0x40; 
    uint8_t total_bytes_sent = 0;
    
    Uart_TxByte(pos_sid); 
    checksum += pos_sid;
    total_bytes_sent++;
    
    for (uint8_t i = 0; i < data_len; i++) {
        Uart_TxByte(data[i]);
        checksum += data[i];
        total_bytes_sent++;
    }
    
    while (total_bytes_sent < 10) {
        Uart_TxByte(0x00);
        checksum += 0x00;
        total_bytes_sent++;
    }
    
    Uart_TxByte(checksum);
    Uart_TxByte(0x0D); 
}

