void Process_DiagnosticService(uint8_t *rx_frame)
{
    uint8_t sid = rx_frame[0]; 
    
    switch (sid)
    {
        case 0x14: 
			{
				for (uint8_t i = 0; i < TOTAL_DTCS; i++)
				{
					g_dtc_table[i].qualifying_status = DEM_STATUS_OK;
					g_dtc_table[i].fault_status = DTC_STATUS_MISSING;
					g_dtc_table[i].debounce_cnt = 0;
					g_dtc_table[i].freeze_frame_data = 0;
				}
				Send_ActiveDTC_Frames();
				Send_PositiveResponse(0x14, NULL, 0);
				break;
            }
		case 0x19: 
            {
                uint8_t sub_function = rx_frame[1]; 
                uint8_t status_mask  = rx_frame[2]; 

                if (sub_function == 0x02)
                {
                    uint8_t resp_data[3];
                    resp_data[0] = sub_function;
                    resp_data[1] = status_mask;
                    resp_data[2] = 0x00; 

                    Send_PositiveResponse(0x19, resp_data, 3);
                    Send_ActiveDTC_Frames();
                }
                else
                {
                    Send_NegativeResponse(sid, 0x12); 
                }
                break;
            }
        case 0x22: 
			{
				uint16_t requested_did = ((rx_frame[1] << 8) | rx_frame[2]);

				if (requested_did == 0x0100)
				{
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], duty_a, duty_b};
					Send_PositiveResponse(0x22, resp_data, 4);
				}
				else if (requested_did == 0x0101)
				{
					uint8_t freq_high = (uint8_t)((target_frequency >> 8) & 0xFF);
					uint8_t freq_low  = (uint8_t)(target_frequency & 0xFF);

					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], freq_high, freq_low };
					Send_PositiveResponse(0x22, resp_data, 4);
				}				
				else if (requested_did == 0x0102) 
				{
					uint8_t setpoint_high = (uint8_t)((g_PidCtrl_TargetSetpoint >> 8) & 0xFF);
					uint8_t setpoint_low  = (uint8_t)(g_PidCtrl_TargetSetpoint & 0xFF);

					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], setpoint_high, setpoint_low };
					Send_PositiveResponse(0x22, resp_data, 4);
				}
				else if (requested_did == 0x0103) 
				{
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], (uint8_t)g_PidCtrl_DisablePidController, 0x00 };
					Send_PositiveResponse(0x22, resp_data, 4);
				}
				else
				{
					Send_NegativeResponse(sid, 0x11);
				}
				break;
			}
		case 0x2E: 
			{
				uint16_t requested_did = ((rx_frame[1] << 8) | rx_frame[2]);

				if (requested_did == 0x0100)
				{
					if (g_PidCtrl_DisablePidController == TRUE)
					{
						duty_a = rx_frame[3];
						duty_b = rx_frame[4];
						uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], duty_a, duty_b}; 
						Send_PositiveResponse(0x2E, resp_data, 4);
					}
					else
					{
						Send_NegativeResponse(sid, 0x22);
					}
				}
				else if (requested_did == 0x0101) 
				{
					target_frequency = ((rx_frame[3] << 8) | rx_frame[4]);
					ICR1 = (uint16_t)(16000000UL / (1UL * target_frequency) - 1);

					uint8_t ICR1_high = (uint8_t)((ICR1 >> 8) & 0xFF);
					uint8_t ICR1_low  = (uint8_t)(ICR1 & 0xFF);

					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], ICR1_high, ICR1_low};
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0102) 
				{
					g_PidCtrl_TargetSetpoint = ((rx_frame[3] << 8) | rx_frame[4]);
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], rx_frame[3], rx_frame[4]};
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0103) 
				{
					g_PidCtrl_DisablePidController = rx_frame[3];
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], rx_frame[3], 0x00};
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0104) 
				{
					uint8_t relay_cmd = rx_frame[3];
					if (relay_cmd == 1) 
					{
						PORTD |= (1 << PD4); 
						g_relay_input_state = 1;
					} 
					else 
					{
						PORTD &= ~(1 << PD4); 
						g_relay_input_state = 0;
					}

					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], relay_cmd, 0x00 };
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0105) 
				{
					uint8_t relay_cmd = rx_frame[3];
					if (relay_cmd == 1) 
 					{
						PORTD |= (1 << PD5); 
						g_relay_output_state = 1;
					} 
					else 
					{
						PORTD &= ~(1 << PD5); 
						g_relay_output_state = 0;
					}

					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], relay_cmd, 0x00 };
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0106) 
				{
					uint8_t activation_flag = rx_frame[3];
					g_toggle_cyclic_fault_mem_updates = (activation_flag == 1) ? TRUE : FALSE;
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], g_toggle_cyclic_fault_mem_updates, 0x00 };
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0107) 
				{
					uint8_t activation_flag = rx_frame[3];
					g_toggle_cyclic_pid_info_updates = (activation_flag == 1) ? TRUE : FALSE;
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], g_toggle_cyclic_pid_info_updates, 0x00 };
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0108) 
				{
					uint8_t activation_flag = rx_frame[3];
					g_toggle_cyclic_pwm_info_updates = (activation_flag == 1) ? TRUE : FALSE;
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], g_toggle_cyclic_pwm_info_updates, 0x00 };
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0109) 
				{
					uint8_t activation_flag = rx_frame[3];
					g_toggle_cyclic_act_info_updates = (activation_flag == 1) ? TRUE : FALSE;
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], g_toggle_cyclic_act_info_updates, 0x00 };
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else if (requested_did == 0x0110) 
				{
					uint8_t activation_flag = rx_frame[3];
					g_toggle_cyclic_conv_info_updates = (activation_flag == 1) ? TRUE : FALSE;
					uint8_t resp_data[4] = { rx_frame[1], rx_frame[2], g_toggle_cyclic_conv_info_updates, 0x00 };
					Send_PositiveResponse(0x2E, resp_data, 4);
				}
				else
				{
					Send_NegativeResponse(0x2E, 0x31);
				}
				break;
			}
		case 0x31: 
			{
				uint8_t sub_function = rx_frame[1];
				uint16_t routine_id = ((rx_frame[2] << 8) | rx_frame[3]);
				
				if (sub_function == 0x01)
				{
					if (routine_id == 0x0201)
					{	
						if (g_PidCtrl_DisablePidController == TRUE)
						{
							g_routine_active_pwm_boost_test = 1; 
							uint8_t resp_data[3] = {sub_function, rx_frame[2], rx_frame[3]};
							Send_PositiveResponse(0x31, resp_data, 3);
						}
						else { Send_NegativeResponse(sid, 0x22); }
					}
					else if (routine_id == 0x0202)
					{
						if (g_PidCtrl_DisablePidController == TRUE)
						{
							g_routine_active_pwm_buck_test = 1; 
							uint8_t resp_data[3] = {sub_function, rx_frame[2], rx_frame[3]};
							Send_PositiveResponse(0x31, resp_data, 3);
						}
						else { Send_NegativeResponse(sid, 0x22); }
					}
					else if (routine_id == 0x0203)
					{	
						if (g_PidCtrl_DisablePidController == FALSE)
						{
							g_routine_active_pid_boost_test = 1; 
							uint8_t resp_data[3] = {sub_function, rx_frame[2], rx_frame[3]};
							Send_PositiveResponse(0x31, resp_data, 3);
						}
						else { Send_NegativeResponse(sid, 0x22); }
					}
					else if (routine_id == 0x0204)
					{
						if (g_PidCtrl_DisablePidController == FALSE)
						{
							g_routine_active_pid_buck_test = 1; 
							uint8_t resp_data[3] = {sub_function, rx_frame[2], rx_frame[3]};
							Send_PositiveResponse(0x31, resp_data, 3);
						}
						else { Send_NegativeResponse(sid, 0x22); }
					}
					else if (routine_id == 0x0205)
					{
						if (g_PidCtrl_DisablePidController == TRUE)
						{
							g_routine_active_input_relay_test = 1; 
							g_timer_input_relay_test_ms = g_tick_ms;
							uint8_t resp_data[4] = {sub_function, rx_frame[2], rx_frame[3], g_routine_active_input_relay_test};
							Send_PositiveResponse(0x31, resp_data, 4);
						}
						else { Send_NegativeResponse(sid, 0x22); }
					}
					else if (routine_id == 0x0206)
					{
						if (g_PidCtrl_DisablePidController == TRUE)
						{
							g_routine_active_output_relay_test = 1; 
							g_timer_output_relay_test_ms = g_tick_ms;
							uint8_t resp_data[4] = {sub_function, rx_frame[2], rx_frame[3], g_routine_active_output_relay_test};
							Send_PositiveResponse(0x31, resp_data, 4);
						}
						else { Send_NegativeResponse(sid, 0x22); }
					}
				}
				else if (sub_function == 0x02) 
				{
					if (rx_frame[2] == 0x02 && rx_frame[3] == 0x01) {g_routine_active_pwm_boost_test = 0;} 
					if (rx_frame[2] == 0x02 && rx_frame[3] == 0x02) {g_routine_active_pwm_buck_test = 0;}  
					if (rx_frame[2] == 0x02 && rx_frame[3] == 0x03) {g_routine_active_pid_boost_test = 0;}
					if (rx_frame[2] == 0x02 && rx_frame[3] == 0x04) {g_routine_active_pid_buck_test = 0;}
					if (rx_frame[2] == 0x02 && rx_frame[3] == 0x05) {g_routine_active_input_relay_test = 0;}
					if (rx_frame[2] == 0x02 && rx_frame[3] == 0x06) {g_routine_active_output_relay_test = 0;}

					uint8_t resp_data[3] = {sub_function, rx_frame[2], rx_frame[3]};
					Send_PositiveResponse(0x31, resp_data, 3);
				}
				else
				{
					Send_NegativeResponse(sid, 0x12); 
				}
				break;
            }
		default:
			{
				Send_NegativeResponse(sid, 0x11);
				break;
			}
    }
}

void Poll_RxParser(void)
{
	while (1)
	{
		uint16_t bytes_available;
		if (s_rx_head >= s_rx_tail) { bytes_available = s_rx_head - s_rx_tail; }
		else { bytes_available = UART_RX_BUF_SIZE - s_rx_tail + s_rx_head; }

		if (bytes_available < FRAME_SIZE) break;

		uint8_t terminator_index = (s_rx_tail + FRAME_SIZE - 1) % UART_RX_BUF_SIZE;
		if (s_rx_buf[terminator_index] == 0x0D)
		{
			uint8_t rx_frame[FRAME_SIZE];

			for (uint8_t i = 0; i < FRAME_SIZE; i++) 
			{
                rx_frame[i] = s_rx_buf[(s_rx_tail + i) % UART_RX_BUF_SIZE];
            }

			uint8_t calc_checksum = 0;
			for (uint8_t i = 0; i < 10; i++)
			{
				calc_checksum += rx_frame[i];
			}

			if (calc_checksum == rx_frame[10])
			{
				for (uint8_t i = 0; i < FRAME_SIZE; i++) 
				{
                    (void)Uart_RxByte(); 
                }
				Process_DiagnosticService(rx_frame);
			}
			else 
            {
                (void)Uart_RxByte();
            }
		}
        else 
        {
            (void)Uart_RxByte();
        }
	}
}

/* ===== Service 0x31 Routine Control ===== */

void Routine_Ctrl_0x31_PWM_Boost_Test(void)
{
	uint32_t g_tick_ms = Rte_Read_TickMs();
	if ((uint32_t)(g_tick_ms - last_bridge_switch_ms) >= 500) 
	{   
		last_bridge_switch_ms = g_tick_ms;
		
		if (bridge_step >= 9)
		{
			bridge_step = 0;
			g_routine_active_pwm_boost_test = 0; 
			uint8_t resp_data[5] = {0x02, 0x02, 0x01, g_routine_active_pwm_boost_test, bridge_step};
			Send_PositiveResponse(0x31, resp_data, 5);
			return;
		}

		bridge_step++;
	}

	switch (bridge_step)
	{
		case 0: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.90f); break;
		case 1: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.80f); break;
		case 2: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.70f); break;
		case 3: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.60f); break;
		case 4: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.50f); break;
		case 5: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.40f); break;
		case 6: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.30f); break;
		case 7: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.20f); break;
		case 8: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.10f); break;
		case 9: OCR1A = (uint16_t)(ICR1 * 0.98f); OCR1B = (uint16_t)(ICR1 * 0.98f); break;
		default: bridge_step = 0; break;
	}
}

