void Routine_Ctrl_0x31_PID_Boost_Test(float vin, float vout)
{
	uint32_t g_tick_ms = Rte_Read_TickMs();
	uint8_t boost_routine_pid_setpoint[10] = {2, 4, 6, 8, 10, 12, 14, 16, 18, 0};
	if ((uint32_t)(g_tick_ms - last_bridge_switch_ms) >= 500)
	{
		last_bridge_switch_ms = g_tick_ms;

		if (bridge_step >= 9)
        {
            bridge_step = 0;
            g_routine_active_pid_boost_test = 0; 
			uint8_t resp_data[5] = {0x02, 0x02, 0x03, g_routine_active_pid_boost_test, bridge_step};
			Send_PositiveResponse(0x31, resp_data, 5);
            return;
        }

		bridge_step++;
	}

    switch (bridge_step)
    {
		case 0: case 1: case 2: case 3: case 4: 
        case 5: case 6: case 7: case 8: case 9: 
			{
				OCR1A = (uint16_t)(ICR1 * 0.98f);

				g_PidCtrl_TargetSetpoint = vin + boost_routine_pid_setpoint[bridge_step];
				float pid_output_boost = PidCtrl_PIDCompute(&g_PidCtrl_PIDConverter, g_PidCtrl_TargetSetpoint, vout, 0.01f);
				g_last_pid_output = pid_output_boost;
				float computed_duty_b = 98.0f - pid_output_boost;
				
				if (computed_duty_b > 98.0f) computed_duty_b = 98.0f;
				if (computed_duty_b < 5.0f) computed_duty_b = 5.0f; 
				
				duty_b = (uint8_t)computed_duty_b;

				break;
			}
		default: bridge_step = 0; break;
    }
}

